CREATE TABLE IF NOT EXISTS `editorialFreedomReviews` (`id` varchar(96) PRIMARY KEY, `articleId` varchar(96) NOT NULL, `rulesetVersion` varchar(64) NOT NULL, `status` enum('pass','review','block') NOT NULL, `score` int NOT NULL, `contentType` varchar(16) NOT NULL, `autonomyAnswer` varchar(16) NOT NULL, `checksJson` text NOT NULL, `actorOpenId` varchar(64) NOT NULL, `createdAtMs` bigint NOT NULL);
